document_store = {
    "doc1": {"content": "The Falcon plan costs twenty dollars per month.", "version": 1},
}
chunk_index = {"doc1_chunk1": {"text": "The Falcon plan costs twenty dollars per month.", "doc_version": 1}}

def detect_change(doc_id, new_content):
    # detecting that a source document changed
    return document_store[doc_id]["content"] != new_content

def apply_incremental_update(doc_id, new_content):
    # updating just the changed chunks, not the entire document
    if not detect_change(doc_id, new_content):
        return "No change detected, skipping update"

    new_version = document_store[doc_id]["version"] + 1
    document_store[doc_id] = {"content": new_content, "version": new_version}

    for chunk_id, chunk in chunk_index.items():
        if chunk_id.startswith(doc_id):
            chunk["text"] = new_content
            chunk["doc_version"] = new_version

    return f"Updated chunks for {doc_id} to version {new_version}"

result = apply_incremental_update("doc1", "The Falcon plan costs twenty dollars per month.")
print(f"First call: {result}")

result = apply_incremental_update("doc1", "The Falcon plan now costs twenty five dollars per month.")
print(f"Second call: {result}")
print(f"Updated chunk: {chunk_index['doc1_chunk1']}")
